import java.nio.file.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public final class AbyssSmokeTest {
 static long frame(Object retriever,long time)throws Exception{Object bitmap=retriever.getClass().getMethod("getFrameAtTime",long.class,int.class).invoke(retriever,time,2);if(bitmap==null)throw new Exception("Video frame unavailable");Class<?> c=bitmap.getClass();int w=(Integer)c.getMethod("getWidth").invoke(bitmap),h=(Integer)c.getMethod("getHeight").invoke(bitmap);Method pixel=c.getMethod("getPixel",int.class,int.class);long sum=1;for(int y=0;y<h;y+=Math.max(1,h/12))for(int x=0;x<w;x+=Math.max(1,w/12))sum=31*sum+(Integer)pixel.invoke(bitmap,x,y);c.getMethod("recycle").invoke(bitmap);return sum;}
 static JSONObject decode(ResolvedStream stream)throws Exception{
  Class<?> clazz=Class.forName("android.media.MediaMetadataRetriever");Object retriever=clazz.getConstructor().newInstance();try{clazz.getMethod("setDataSource",String.class,Map.class).invoke(retriever,stream.url,AbyssClient.mediaHeaders(stream.referer));Method meta=clazz.getMethod("extractMetadata",int.class);long duration=Long.parseLong((String)meta.invoke(retriever,9));String audio=(String)meta.invoke(retriever,16),video=(String)meta.invoke(retriever,17);if(duration<90000||!"yes".equals(audio)||!"yes".equals(video))throw new Exception("Full audio/video metadata unavailable");long a=frame(retriever,30000000),b=frame(retriever,60000000);if(a==b)throw new Exception("Identical distant video frames");return new JSONObject().put("durationMs",duration).put("audio",audio).put("video",video).put("decodedFrames",2).put("differentFrames",true);}finally{clazz.getMethod("release").invoke(retriever);}
 }
 public static void main(String[] args)throws Exception{
  JSONArray fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get(args[0])),"UTF-8")).getJSONArray("fixtures"),results=new JSONArray();int pass=0;
  for(int i=0;i<fixtures.length();i++){JSONObject f=fixtures.getJSONObject(i),result=new JSONObject().put("title",f.getString("title"));NativeHttp.CURRENT.set(new NativeHttp.Session(30000));long start=System.nanoTime();try{List<NativeCatalog.Candidate> found=new FdCatalog().discover(f.getJSONObject("data"));NativeCatalog.Candidate selected=null;for(NativeCatalog.Candidate c:found)if(c.host.equals("Abyss")){selected=c;break;}if(selected==null)throw new Exception("No Abyss candidate");ResolvedStream stream=RoDubbedProvider.resolve(selected);Object link=RoDubbedProvider.makeLink(stream);if(!link.getClass().getMethod("getType").invoke(link).toString().equals("VIDEO"))throw new Exception("Wrong native link type");result.put("host",stream.host).put("quality",stream.quality).put("decoded",decode(stream)).put("pass",true);pass++;}catch(Throwable e){Throwable cause=e instanceof InvocationTargetException?((InvocationTargetException)e).getCause():e;result.put("pass",false).put("error",cause.toString());}finally{NativeHttp.session().stop();NativeHttp.CURRENT.remove();}result.put("ms",(System.nanoTime()-start)/1000000);results.put(result);System.out.println(result.toString());}
  Files.write(Paths.get(args[1]),new JSONObject().put("passed",pass).put("total",fixtures.length()).put("results",results).toString(2).getBytes("UTF-8"));
 }
}
